    return G

G_all = load_grids()
demo_in = G_all['Demo pair 1 input']
demo_out = G_all['Demo pair 1 output']

actual_2s = {(i,j) for i in range(21) for j in range(25) if demo_out[i][j] == 2}
reachable = set()

# BFS to find reachable with distance tracking
queue = deque()
dist = {}
for i in range(21):
    for j in range(25):
        if demo_in[i][j] == 2:
            dist[(i,j)] = 0
            queue.append((i,j))

while queue:
    i, j = queue.popleft()
    for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
        ni, nj = i + di, j + dj
        if 0 <= ni < 21 and 0 <= nj < 25 and (ni,nj) not in dist and demo_in[ni][nj] != 8:
            dist[(ni,nj)] = dist[(i,j)] + 1
            queue.append((ni,nj))

print("=== Distance analysis ===")
dist_of_actual_2s = {p: dist[p] for p in actual_2s}
max_dist = max(dist_of_actual_2s.values()) if dist_of_actual_2s else 0
min_dist = min(dist_of_actual_2s.values()) if dist_of_actual_2s else float('inf')
print(f"Min dist from 2-block: {min_dist}, Max dist: {max_dist}")

# Check distribution
dist_counts = {}
for d in dist_of_actual_2s.values():
    dist_counts[d] = dist_counts.get(d, 0) + 1
print("\nDist counts:", dict(sorted(dist_counts.items())))

# What about non-2 reachable cells?
not_2_reachable = [(i,j) for (i,j),d in dist.items() if d > 0 and (i,j) not in actual_2s]
if not_2_reachable:
    not_2_dists = [dist[p] for p in not_2_reachable]
    print(f"\nNon-2 reachable count: {len(not_2_reachable)}")
    print(f"Non-2 min/max dist: {min(not_2_dists)}, {max(not_2_dists)}")
    # Show some examples
    for p, d in sorted([(p,d) for p in not_2_reachable if dist.get(p)]):
        if dist[p] <= 15:
            print(f"{p}: dist={dist[p]}, value={demo_out[p[0]][p[1]]}")

