actual_2s = {(i,j) for i in range(21) for j in range(25) if demo_out[i][j] == 2}
eight_pos = [(i,j) for i in range(21) for j in range(25) if demo_in[i][j] == 8]

def min_dist_to_eight(pos):
    i, j = pos
    best = float('inf')
