# Function to expand from 2-block via row/col only
def expand_row_col_only(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    expanded = set()

    for i in range(h):
        for j in range(w):
            if input_grid[i][j] == 2:
                # Expand left
                for col in range(j-1, -1, -1):
                    if input_grid[i][col] == 8:
                        break
                    expanded.add((i, col))
                # Expand right
                for col in range(j+1, w):
                    if input_grid[i][col] == 8:
                        break
                    expanded.add((i, col))
                # Expand up
                for row in range(i-1, -1, -1):
                    if input_grid[row][j] == 8:
                        break
                    expanded.add((row, j))
                # Expand down
                for row in range(i+1, h):
                    if input_grid[row][j] == 8:
                        break
                    expanded.add((row, j))

    return expanded

