G_all = load_grids()
demo_in = G_all['Demo pair 1 input']
demo_out = G_all['Demo pair 1 output']

# What if the rule is: each cell becomes 2 iff it can reach the 2-block by moving only up/down/left/right
# without ever passing through a cell whose Manhattan distance to nearest 8 is <= K?
# (K could be different for different positions?)

from collections import deque

eight_pos = [(i,j) for i in range(21) for j in range(25) if demo_in[i][j] == 8]

for dist_limit in range(1, 6):
    # Build blocked set: cells within dist_limit of any 8 (excluding 8s themselves)
    blocked = set()
    for ei, ej in eight_pos:
        for di in range(-dist_limit, dist_limit+1):
            for dj in range(-dist_limit, dist_limit+1):
                ni, nj = ei + di, ej + dj
                if 0 <= ni < 21 and 0 <= nj < 25 and (ni,nj) not in eight_pos:
                    if abs(di)+abs(dj) <= dist_limit:
                        blocked.add((ni,nj))

    print(f"\n=== dist_limit={dist_limit} ===")
    print(f"Blocked cells count: {len(blocked)}")

    # Check which actual_2s would be cut off
    unreachable = set()
    visited = set()
    queue = deque([(r,c) for r in range(1,9) for c in range(2,10)])
    while queue:
        i, j = queue.popleft()
        if (i,j) in visited:
            continue
        visited.add((i,j))
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < 21 and 0 <= nj < 25:
                if (ni,nj) not in visited and (ni,nj) not in blocked and demo_in[ni][nj] != 8:
                    queue.append((ni,nj))

    reachable_but_not_2 = visited - actual_2s
    covered_2s = visited & actual_2s

    print(f"Covered 2s: {len(covered_2s)}, Unreachable 2s: {len(actual_2s - visited)}")
    print(f"Extra reachable (not 2): {len(reachable_but_not_2)}")

