import numpy as np

def predict_demo3():
    # Based on comprehensive analysis
    output = np.zeros((20, 17), dtype=int)

    # Original block
    block_r_start, block_r_end = 4, 9
    block_c_start, block_c_end = 5, 10

    for r in range(block_r_start, block_r_end + 1):
        for c in range(block_c_start, block_c_end + 1):
            output[r,c] = 2

    # Step 1: Block rows expand horizontally based on anchors ON THAT ROW
    for r in range(20):
        row_anchors = [ac for ar,ac in [(1,6),(1,10),(4,2),(7,1),(8,2),(9,14),(13,5),(14,9)] if ar == r]
        if not row_anchors:
            continue

        all_left_of_block = all(ac < block_c_start for ac in row_anchors)
        all_right_of_block = all(ac > block_c_end for ac in row_anchors)

        if all_left_of_block:
            # Fill from first anchor to grid right edge
            for c in range(min(row_anchors), 17):
                output[r,c] = 2
        elif all_right_of_block:
            # Fill from last anchor to grid left edge  
            for c in range(17):
                output[r,c] = 2

            # Actually, fill LEFTWARD to block start
            for c in range(max(row_anchors), block_c_start - 1, -1):
                output[r,c] = 2

    # Step 2: Block columns expand vertically based on anchors IN THAT COLUMN
    for c in range(block_c_start, block_c_end + 1):
        col_anchors = [ar for ar,ac in [(1,6),(1,10),(4,2),(7,1),(8,2),(9,14),(13,5),(14,9)] if ac == c]

        if not col_anchors:
            # Interior column with no anchors → FULLY VERTICALLY FILLED
            for r in range(20):
                output[r,c] = 2
        else:
            min_a = min(col_anchors)
            max_a = max(col_anchors)

            # Fill based on anchor positions relative to block
            if min_a < block_r_start and not any(r for r in col_anchors if block_r_start <= r <= block_r_end):
                # Anchor(s) ABOVE and NONE in block → fill DOWN from first anchor
                for r in range(min_a, 20):
                    output[r,c] = 2

            elif max_a > block_r_end and not any(r for r in col_anchors if block_r_start <= r <= block_r_end):
                # Anchor(s) BELOW and NONE in block → fill UP from last anchor
                for r in range(max_a, -1, -1):
                    output[r,c] = 2

    return output

# Test
result = predict_demo3()
